-- mistri store layout: tenant-administration, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_tenant_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1),
  app_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL
);
CREATE TABLE "__mistri_tenant_tenant" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'suspended', 'closed')),
  version TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('tenant', 'platform')),
  CHECK ((kind = 'platform') = (id = '@platform'))
);
CREATE TABLE "__mistri_tenant_membership" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  tenant_id TEXT COLLATE BINARY NOT NULL REFERENCES "__mistri_tenant_tenant" (id) ON DELETE RESTRICT,
  account_id TEXT COLLATE BINARY NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'revoked', 'invited')),
  version TEXT NOT NULL,
  roles_json TEXT NOT NULL CHECK (json_valid(roles_json) AND length(CAST(roles_json AS BLOB)) <= 262144),
  valid_until INTEGER NOT NULL CHECK (valid_until >= 0 AND valid_until <= 9007199254740991),
  kind TEXT NOT NULL CHECK (kind IN ('member', 'support')),
  parent_id TEXT COLLATE BINARY REFERENCES "__mistri_tenant_membership" (id) ON DELETE RESTRICT,
  parent_version TEXT,
  platform_version TEXT,
  CHECK ((kind = 'support') = (parent_id IS NOT NULL AND parent_version IS NOT NULL AND platform_version IS NOT NULL)),
  CHECK (kind = 'member' OR status IN ('active', 'revoked'))
);
CREATE UNIQUE INDEX "__mistri_tenant_live_membership" ON "__mistri_tenant_membership" (tenant_id, account_id) WHERE status != 'revoked' AND kind = 'member';
CREATE UNIQUE INDEX "__mistri_tenant_live_support" ON "__mistri_tenant_membership" (account_id) WHERE kind = 'support' AND status = 'active';
CREATE UNIQUE INDEX "__mistri_tenant_platform" ON "__mistri_tenant_tenant" (kind) WHERE kind = 'platform';
CREATE TABLE "__mistri_admin_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1),
  app_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(app_id) = 'text' AND length(CAST(app_id AS BLOB)) BETWEEN 1 AND 1024),
  source_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(source_id) = 'text' AND length(CAST(source_id AS BLOB)) BETWEEN 1 AND 256),
  store_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(store_id) = 'text' AND length(CAST(store_id AS BLOB)) BETWEEN 1 AND 1024)
);
CREATE TABLE "__mistri_admin_receipt" (
  id TEXT COLLATE BINARY NOT NULL CHECK (typeof(id) = 'text' AND length(CAST(id AS BLOB)) BETWEEN 1 AND 1024) PRIMARY KEY,
  actor_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(actor_id) = 'text' AND length(CAST(actor_id AS BLOB)) BETWEEN 1 AND 1024),
  tenant_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(tenant_id) = 'text' AND length(CAST(tenant_id AS BLOB)) BETWEEN 1 AND 128),
  operation TEXT COLLATE BINARY NOT NULL CHECK (typeof(operation) = 'text' AND length(CAST(operation AS BLOB)) BETWEEN 1 AND 256),
  operation_version INTEGER NOT NULL CHECK (typeof(operation_version) = 'integer' AND operation_version BETWEEN 1 AND 9007199254740991),
  idempotency_key TEXT COLLATE BINARY NOT NULL CHECK (typeof(idempotency_key) = 'text' AND length(CAST(idempotency_key AS BLOB)) BETWEEN 1 AND 256),
  fingerprint TEXT COLLATE BINARY NOT NULL CHECK (typeof(fingerprint) = 'text' AND length(CAST(fingerprint AS BLOB)) BETWEEN 1 AND 256),
  result_json TEXT NOT NULL CHECK (json_valid(result_json) AND length(CAST(result_json AS BLOB)) <= 16384),
  request_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(request_id) = 'text' AND length(CAST(request_id AS BLOB)) BETWEEN 1 AND 1024),
  completed_at TEXT COLLATE BINARY NOT NULL CHECK (typeof(completed_at) = 'text' AND length(CAST(completed_at AS BLOB)) BETWEEN 1 AND 32),
  policy_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(policy_id) = 'text' AND length(CAST(policy_id AS BLOB)) BETWEEN 1 AND 256),
  policy_version TEXT COLLATE BINARY NOT NULL CHECK (typeof(policy_version) = 'text' AND length(CAST(policy_version AS BLOB)) BETWEEN 1 AND 256),
  deployment TEXT COLLATE BINARY NOT NULL CHECK (typeof(deployment) = 'text' AND length(CAST(deployment AS BLOB)) BETWEEN 1 AND 256),
  session_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(session_id) = 'text' AND length(CAST(session_id AS BLOB)) BETWEEN 1 AND 1024),
  change_json TEXT NOT NULL CHECK (json_valid(change_json) AND length(CAST(change_json AS BLOB)) <= 65536),
  UNIQUE (actor_id, tenant_id, operation, operation_version, idempotency_key)
);
